// One-shot isolated migration validation. Creates a throwaway database,
// applies the full migration chain with `prisma migrate deploy`, then drops it.
// Never touches the development database.
const { spawnSync } = require("node:child_process");
const fs = require("node:fs");
const path = require("node:path");
const { Client } = require("pg");

const readDotEnvDatabaseUrl = () => {
  const envPath = path.join(process.cwd(), ".env");
  const content = fs.readFileSync(envPath, "utf8");
  const line = content.split(/\r?\n/).find((l) => l.trim().startsWith("DATABASE_URL="));
  if (!line) throw new Error("DATABASE_URL not found in .env");
  return line.slice("DATABASE_URL=".length).trim().replace(/^"|"$/g, "");
};

const main = async () => {
  const baseUrl = readDotEnvDatabaseUrl();
  const dbName = `aventra_mastertest_${Date.now()}`;
  const admin = new Client({ connectionString: baseUrl });
  await admin.connect();
  await admin.query(`CREATE DATABASE "${dbName}"`);
  await admin.end();
  const isolatedUrl = baseUrl.replace(/\/[^/?]+(\?|$)/, `/${dbName}$1`);
  console.log(`created isolated database ${dbName}`);
  try {
    const result = spawnSync("npx", ["prisma", "migrate", "deploy"], {
      env: { ...process.env, DATABASE_URL: isolatedUrl },
      encoding: "utf8",
      timeout: 300000,
    });
    console.log(result.stdout);
    console.error(result.stderr);
    if (result.status !== 0) {
      throw new Error(`migrate deploy failed with status ${result.status}`);
    }
    console.log("MIGRATE_DEPLOY_OK");
  } finally {
    const admin2 = new Client({ connectionString: baseUrl });
    await admin2.connect();
    await admin2.query(`DROP DATABASE IF EXISTS "${dbName}" WITH (FORCE)`);
    await admin2.end();
    console.log(`dropped isolated database ${dbName}`);
  }
};

main().catch((err) => {
  console.error(`VALIDATION_FAILED: ${err instanceof Error ? err.message : err}`);
  process.exit(1);
});

