export type CategoryStatus = "ACTIVE" | "INACTIVE";

export type Category = {
  id: string;
  organizationId: string;
  name: string;
  description?: string | null;
  status: CategoryStatus;
  createdAt: Date;
  updatedAt: Date;
};

export type CategoryListFilter = {
  status?: CategoryStatus | "ALL";
  query?: string;
  limit?: number;
  offset?: number;
};

export const normalizeCategoryName = (name: string): string =>
  name.trim().replace(/\s+/g, " ");

export const getCategoryInitials = (name: string): string => {
  const parts = normalizeCategoryName(name).split(" ").filter(Boolean);
  if (parts.length === 0) return "?";
  if (parts.length === 1) return (parts[0]?.slice(0, 2) ?? "?").toUpperCase();
  return `${parts[0]?.slice(0, 1) ?? ""}${parts[parts.length - 1]?.slice(0, 1) ?? ""}`.toUpperCase();
};

export class CategoryDomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "CategoryDomainError";
  }
}

export class CategoryNotFoundError extends CategoryDomainError {
  constructor(id: string) {
    super(`Category with ID "${id}" was not found.`);
    this.name = "CategoryNotFoundError";
  }
}

export class CategoryDuplicateError extends CategoryDomainError {
  constructor(name: string) {
    super(`A category named "${name}" already exists in this organization.`);
    this.name = "CategoryDuplicateError";
  }
}

export class CategoryInUseError extends CategoryDomainError {
  constructor(name: string, itemCount: number) {
    super(
      `Category "${name}" cannot be deleted because it is used by ${itemCount} catalogue item${itemCount === 1 ? "" : "s"}. Reassign those items first.`,
    );
    this.name = "CategoryInUseError";
  }
}

export class UnauthorizedCategoryAccessError extends CategoryDomainError {
  constructor(message = "You are not authorized to access this category resource.") {
    super(message);
    this.name = "UnauthorizedCategoryAccessError";
  }
}

export class ForbiddenCategoryActionError extends CategoryDomainError {
  constructor(message = "You don't have permission to perform this category action.") {
    super(message);
    this.name = "ForbiddenCategoryActionError";
  }
}

import type { Category, CategoryListFilter } from "../entities/category";

export type CategoryListResult = {
  categories: Category[];
  totalCount: number;
};

export type ICategoryRepository = {
  findById(organizationId: string, id: string): Promise<Category | null>;
  findByName(organizationId: string, name: string): Promise<Category | null>;
  list(organizationId: string, filter?: CategoryListFilter): Promise<CategoryListResult>;
  create(category: Category): Promise<Category>;
  update(organizationId: string, id: string, patch: Partial<Category>): Promise<Category>;
  delete(organizationId: string, id: string): Promise<void>;
};

import { CategoryDomainError } from "../errors/category-errors";
import { normalizeCategoryName } from "../entities/category";

export const CATEGORY_NAME_MIN_LENGTH = 2;

export const CATEGORY_NAME_MAX_LENGTH = 100;

export const CATEGORY_DESCRIPTION_MAX_LENGTH = 500;

export const validateCategoryName = (name: string): string => {
  const normalized = normalizeCategoryName(name);
  if (normalized.length < CATEGORY_NAME_MIN_LENGTH) {
    throw new CategoryDomainError("Category name must be at least 2 characters.");
  }
  if (normalized.length > CATEGORY_NAME_MAX_LENGTH) {
    throw new CategoryDomainError("Category name cannot exceed 100 characters.");
  }
  return normalized;
};

/**
 * Standard catalogue categories shipped as seed data. These mirror the legacy
 * free-text options so organizations adopting the master keep working values.
 */
export const DEFAULT_CATEGORIES: readonly { name: string; description: string }[] = [
  { name: "General", description: "Default catch-all category for uncategorized items." },
  { name: "Hardware", description: "Physical goods, devices, and equipment." },
  { name: "Software", description: "Licenses, applications, and digital products." },
  { name: "Consulting", description: "Advisory and professional services." },
  { name: "Maintenance", description: "Support, repair, and upkeep services." },
  { name: "Subscription", description: "Recurring plans and memberships." },
  { name: "Logistics", description: "Transport, delivery, and warehousing services." },
  { name: "Office Supplies", description: "Consumables and day-to-day office goods." },
];

export * from "./entities/category";
export * from "./errors/category-errors";
export * from "./repositories/category-repository";
export * from "./rules/category-rules";

import { describe, expect, it } from "vitest";
import { normalizeCategoryName, getCategoryInitials } from "./entities/category";
import { validateCategoryName, DEFAULT_CATEGORIES } from "./rules/category-rules";
import { CategoryDomainError } from "./errors/category-errors";

describe("category domain rules", () => {
  it("normalizes names by trimming and collapsing whitespace", () => {
    expect(normalizeCategoryName("  Office   Supplies ")).toBe("Office Supplies");
  });

  it("accepts valid names and rejects short or long names", () => {
    expect(validateCategoryName("Hardware")).toBe("Hardware");
    expect(() => validateCategoryName("A")).toThrow(CategoryDomainError);
    expect(() => validateCategoryName("x".repeat(101))).toThrow(CategoryDomainError);
  });

  it("derives initials for badges", () => {
    expect(getCategoryInitials("Hardware")).toBe("HA");
    expect(getCategoryInitials("Office Supplies")).toBe("OS");
  });

  it("ships the legacy standard categories as seed data", () => {
    const names = DEFAULT_CATEGORIES.map((c) => c.name);
    expect(names).toEqual([
      "General",
      "Hardware",
      "Software",
      "Consulting",
      "Maintenance",
      "Subscription",
      "Logistics",
      "Office Supplies",
    ]);
  });
});

import type { CategoryStatus } from "../../domain/entities/category";

export type CategoryDto = {
  id: string;
  organizationId: string;
  name: string;
  description?: string | null;
  status: CategoryStatus;
  createdAt: string;
  updatedAt: string;
};

export type CreateCategoryInput = {
  name: string;
  description?: string | null;
};

export type UpdateCategoryInput = Partial<CreateCategoryInput> & {
  status?: CategoryStatus;
};

export type CategoryFilterInput = {
  query?: string;
  status?: CategoryStatus | "ALL";
  page?: number;
  pageSize?: number;
};

export type CategoryActionResult<T> = {
  success: boolean;
  data?: T;
