  fieldErrors?: Record<string, string>;
};

import type { Category } from "../../domain/entities/category";
import type { CategoryDto } from "../dto/category-dto";

export const toCategoryDto = (c: Category): CategoryDto => ({
  id: c.id,
  organizationId: c.organizationId,
  name: c.name,
  description: c.description ?? null,
  status: c.status,
  createdAt: c.createdAt instanceof Date ? c.createdAt.toISOString() : String(c.createdAt),
  updatedAt: c.updatedAt instanceof Date ? c.updatedAt.toISOString() : String(c.updatedAt),
});

import { z } from "zod";
import {
  CATEGORY_DESCRIPTION_MAX_LENGTH,
  CATEGORY_NAME_MAX_LENGTH,
  CATEGORY_NAME_MIN_LENGTH,
} from "../../domain/rules/category-rules";

const categoryStatusSchema = z.enum(["ACTIVE", "INACTIVE"]);

export const createCategorySchema = z.object({
  name: z
    .string()
    .trim()
    .min(CATEGORY_NAME_MIN_LENGTH, "Category name must be at least 2 characters.")
    .max(CATEGORY_NAME_MAX_LENGTH, "Category name cannot exceed 100 characters."),
  description: z
    .string()
    .trim()
    .max(CATEGORY_DESCRIPTION_MAX_LENGTH, "Description cannot exceed 500 characters.")
    .optional()
    .nullable()
    .transform((val) => (val && val.trim().length > 0 ? val.trim() : null)),
});

export const updateCategorySchema = z.object({
  name: z
    .string()
    .trim()
    .min(CATEGORY_NAME_MIN_LENGTH, "Category name must be at least 2 characters.")
    .max(CATEGORY_NAME_MAX_LENGTH, "Category name cannot exceed 100 characters.")
    .optional(),
  description: z
    .string()
    .trim()
    .max(CATEGORY_DESCRIPTION_MAX_LENGTH, "Description cannot exceed 500 characters.")
    .optional()
    .nullable()
    .transform((val) => (val === undefined ? undefined : val && val.trim().length > 0 ? val.trim() : null)),
  status: categoryStatusSchema.optional(),
});

export const categoryFilterSchema = z.object({
  query: z.string().trim().optional(),
  status: z.enum(["ALL", "ACTIVE", "INACTIVE"]).default("ALL"),
  page: z.coerce.number().int().min(1).default(1),
  pageSize: z.coerce.number().int().min(1).max(100).default(10),
});

import "server-only";

import { getAuthState } from "@/features/auth";
import {
  CategoryDomainError,
  UnauthorizedCategoryAccessError,
} from "../../domain/errors/category-errors";

export type CategoryContext = {
  organizationId: string;
  userId: string;
  memberRole: string;
};

export const resolveCategoryContext = async (): Promise<CategoryContext> => {
  const state = await getAuthState();

  if (state.status !== "authenticated") {
    throw new UnauthorizedCategoryAccessError();
  }

  if (state.organization === null) {
    throw new CategoryDomainError("Active organization context is missing.");
  }

  return {
    organizationId: state.organization.id,
    userId: state.user.id,
    memberRole: state.organization.role,
  };
};

import "server-only";

import { resolveCategoryContext } from "../context/category-context";
import { categoryRepository } from "../../infrastructure/repositories/prisma-category-repository";
import { toCategoryDto } from "../mappers/category-mappers";
import type { CategoryDto, CategoryFilterInput } from "../dto/category-dto";

export type GetCategoriesResult = {
  categories: CategoryDto[];
  totalCount: number;
};

export const getCategories = async (
  filter?: CategoryFilterInput,
): Promise<GetCategoriesResult> => {
  const { organizationId } = await resolveCategoryContext();

  const page = filter?.page ?? 1;
  const pageSize = filter?.pageSize ?? 10;

  const result = await categoryRepository.list(organizationId, {
    status: filter?.status,
    query: filter?.query,
    limit: pageSize,
    offset: (page - 1) * pageSize,
  });

  return {
    categories: result.categories.map(toCategoryDto),
    totalCount: result.totalCount,
  };
};

