"use client";

import Link from "next/link";
import { Edit2, Eye, SearchX, Tags } from "lucide-react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/shared/components/table";
import { getCategoryInitials } from "../../domain/entities/category";
import type { CategoryDto } from "../../data/dto/category-dto";

export type CategoryTableProps = {
  categories: CategoryDto[];
  usageCounts?: Record<string, number>;
  isFiltered?: boolean;
  onClearFilters?: () => void;
};

export const CategoryTable = ({
  categories,
  usageCounts = {},
  isFiltered = false,
  onClearFilters,
}: CategoryTableProps) => {
  if (categories.length === 0) {
    if (isFiltered) {
      return (
        <div className="flex flex-col items-center justify-center rounded-xl border border-border bg-surface-card p-12 text-center">
          <div className="flex h-12 w-12 items-center justify-center rounded-full bg-surface-alt text-text-muted">
            <SearchX size={24} />
          </div>
          <h3 className="mt-4 text-base font-semibold text-text-primary">
            No matching categories
          </h3>
          <p className="mt-1 max-w-sm text-sm text-text-secondary">
            No categories matched your search query or filter criteria.
          </p>
          {onClearFilters && (
            <button
              type="button"
              onClick={onClearFilters}
              className="mt-4 inline-flex h-9 items-center justify-center rounded-lg border border-border bg-surface-alt px-4 text-xs font-medium text-text-primary transition-colors hover:border-text-muted hover:bg-surface cursor-pointer"
            >
              Clear filters
            </button>
          )}
        </div>
      );
    }

    return (
      <div className="flex flex-col items-center justify-center rounded-xl border border-border bg-surface-card p-12 text-center">
        <div className="flex h-12 w-12 items-center justify-center rounded-full bg-surface-alt text-text-muted">
          <Tags size={24} />
        </div>
        <h3 className="mt-4 text-base font-semibold text-text-primary">
          No categories yet
        </h3>
        <p className="mt-1 max-w-sm text-sm text-text-secondary">
          Seed the standard categories or create your first category to organize products and services.
        </p>
        <Link
          href="/categories/new"
          className="mt-4 inline-flex h-9 items-center justify-center rounded-lg bg-primary px-4 text-xs font-medium text-primary-foreground transition-colors hover:bg-primary-light"
        >
          + Add Category
        </Link>
      </div>
    );
  }

  return (
    <div className="overflow-hidden rounded-xl border border-border bg-surface-card">
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead className="w-[38%]">Category</TableHead>
            <TableHead className="w-[30%]">Description</TableHead>
            <TableHead className="w-[10%] text-center">Items</TableHead>
            <TableHead className="w-[12%] text-center">Status</TableHead>
            <TableHead className="w-[80px] text-right">Actions</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {categories.map((c) => {
            const isActive = c.status === "ACTIVE";
            const detailHref = `/categories/${c.id}`;
            const editHref = `/categories/${c.id}/edit`;
            const usage = usageCounts[c.name];

            return (
              <TableRow key={c.id} className="group">
                <TableCell>
                  <div className="flex items-center gap-3">
                    <div
                      className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border border-border/80 bg-surface-alt text-xs font-semibold text-primary-light"
                      aria-hidden="true"
                    >
                      {getCategoryInitials(c.name)}
                    </div>
                    <Link
                      href={detailHref}
                      className="truncate text-sm font-medium text-text-primary group-hover:text-primary-light transition-colors hover:underline block"
                    >
                      {c.name}
                    </Link>
                  </div>
                </TableCell>

                <TableCell>
                  {c.description ? (
                    <span className="block truncate text-xs text-text-secondary max-w-xs">
                      {c.description}
                    </span>
                  ) : (
                    <span className="text-xs text-text-muted">—</span>
                  )}
                </TableCell>

                <TableCell className="text-center">
                  <span className="text-xs font-mono text-text-secondary">
                    {usage === undefined ? "—" : usage}
                  </span>
                </TableCell>

                <TableCell className="text-center">
                  <span
                    className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-0.5 text-xs font-medium ${
                      isActive
                        ? "bg-success/15 text-success"
                        : "bg-surface-alt text-text-muted border border-border/80"
                    }`}
                  >
                    <span
                      className={`h-1.5 w-1.5 rounded-full ${
                        isActive ? "bg-success" : "bg-text-muted"
                      }`}
                      aria-hidden="true"
                    />
                    {isActive ? "Active" : "Inactive"}
                  </span>
                </TableCell>

                <TableCell className="text-right">
                  <div className="flex items-center justify-end gap-1">
                    <Link
                      href={detailHref}
                      aria-label={`View details for ${c.name}`}
                      className="inline-flex h-8 w-8 items-center justify-center rounded-lg border border-border/60 text-text-secondary transition-colors hover:border-text-muted hover:bg-surface-alt hover:text-text-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-focus"
                    >
                      <Eye size={13} />
                    </Link>
                    <Link
                      href={editHref}
                      aria-label={`Edit ${c.name}`}
                      className="inline-flex h-8 w-8 items-center justify-center rounded-lg border border-border/60 text-text-secondary transition-colors hover:border-text-muted hover:bg-surface-alt hover:text-text-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-focus"
                    >
                      <Edit2 size={13} />
                    </Link>
                  </div>
                </TableCell>
              </TableRow>
            );
          })}
        </TableBody>
      </Table>
    </div>
  );
};

"use client";

import { RotateCcw, Search } from "lucide-react";
import { Input, Select } from "@/shared/components/form";
import type { CategoryStatus } from "../../domain/entities/category";

export type CategoryFilterBarProps = {
  query: string;
  onQueryChange: (val: string) => void;
  status: CategoryStatus | "ALL";
  onStatusChange: (val: CategoryStatus | "ALL") => void;
  onReset: () => void;
};

const statusOptions = [
  { value: "ALL", label: "All Statuses" },
  { value: "ACTIVE", label: "Active" },
  { value: "INACTIVE", label: "Inactive" },
];

export const CategoryFilterBar = ({
  query,
  onQueryChange,
  status,
  onStatusChange,
  onReset,
}: CategoryFilterBarProps) => {
  const hasActiveFilters = query.trim().length > 0 || status !== "ALL";

  return (
    <div className="flex flex-col gap-3 rounded-xl border border-border bg-surface-card p-3 sm:flex-row sm:items-center">
      <div className="min-w-0 flex-1">
        <Input
          id="category-search"
          type="search"
          value={query}
          onChange={(e) => onQueryChange(e.target.value)}
          placeholder="Search categories by name or description..."
          startIcon={<Search size={16} />}
          aria-label="Search categories"
          className="h-10 text-sm"
        />
      </div>

      <div className="w-full sm:w-36 shrink-0">
        <Select
          id="filter-category-status"
          value={status}
          onChange={(val) => onStatusChange(val as CategoryStatus | "ALL")}
          options={statusOptions}
          aria-label="Filter by status"
          className="h-10 text-sm"
        />
      </div>

      {hasActiveFilters && (
        <button
          type="button"
          onClick={onReset}
          className="inline-flex h-10 items-center justify-center gap-1.5 rounded-lg border border-border bg-surface-alt px-3 text-xs font-medium text-text-secondary transition-colors hover:border-text-muted hover:text-text-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-focus cursor-pointer shrink-0"
          aria-label="Reset filters"
        >
          <RotateCcw size={14} />
          <span>Reset</span>
        </button>
      )}
    </div>
  );
};

"use client";

import { Tags } from "lucide-react";
import { Input, Label, Select, Textarea } from "@/shared/components/form";
import type { CategoryStatus } from "../../domain/entities/category";

export type CategoryDetailsSectionProps = {
  name: string;
  onNameChange: (val: string) => void;
  description: string;
  onDescriptionChange: (val: string) => void;
  status: CategoryStatus;
  onStatusChange: (val: CategoryStatus) => void;
  errors?: Record<string, string>;
};

const statusOptions = [
  { value: "ACTIVE", label: "Active" },
  { value: "INACTIVE", label: "Inactive" },
];

export const CategoryDetailsSection = ({
  name,
  onNameChange,
  description,
  onDescriptionChange,
  status,
  onStatusChange,
  errors = {},
}: CategoryDetailsSectionProps) => {
  return (
    <section className="rounded-xl border border-border bg-surface-card p-5 sm:p-6">
      <div className="flex items-center gap-3 border-b border-border/60 pb-4">
        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-surface-alt text-primary-light">
          <Tags size={18} />
        </div>
        <div>
          <h2 className="text-base font-semibold text-text-primary">
            Category Details
          </h2>
          <p className="text-xs text-text-secondary">
            Name, description, and availability for catalogue items.
          </p>
        </div>
      </div>

      <div className="mt-5 grid grid-cols-1 gap-4 sm:grid-cols-2">
        <div className="space-y-1.5">
          <Label htmlFor="category-name" className="text-xs">
            Category Name <span className="text-danger">*</span>
          </Label>
          <Input
            id="category-name"
            value={name}
            onChange={(e) => onNameChange(e.target.value)}
            placeholder="e.g., Hardware"
            aria-invalid={Boolean(errors.name)}
            className="h-10 text-sm"
          />
          {errors.name && (
            <p className="text-xs text-danger" role="alert">
              {errors.name}
            </p>
          )}
        </div>

        <div className="space-y-1.5">
          <Label htmlFor="category-status" className="text-xs">
            Status <span className="text-danger">*</span>
          </Label>
          <Select
            id="category-status"
            value={status}
            onChange={(val) => onStatusChange(val as CategoryStatus)}
            options={statusOptions}
            className="h-10 text-sm"
          />
          {errors.status && (
            <p className="text-xs text-danger" role="alert">
              {errors.status}
            </p>
          )}
        </div>

        <div className="space-y-1.5 sm:col-span-2">
          <Label htmlFor="category-description" className="text-xs">
            Description
          </Label>
          <Textarea
            id="category-description"
            value={description}
            onChange={(e) => onDescriptionChange(e.target.value)}
            placeholder="What belongs in this category..."
            rows={3}
            className="text-sm resize-none"
          />
          {errors.description && (
            <p className="text-xs text-danger" role="alert">
              {errors.description}
            </p>
          )}
        </div>
      </div>
    </section>
  );
};

"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { Check, Loader2, Plus, X } from "lucide-react";
import { useState, useTransition } from "react";
import { Button } from "@/shared/components/form/Button";
import type { CategoryDto, CreateCategoryInput } from "../../data/dto/category-dto";
import type { CategoryStatus } from "../../domain/entities/category";
import { createCategoryAction } from "../../data/mutations/create-category";
import { updateCategoryAction } from "../../data/mutations/update-category";
import { CategoryDetailsSection } from "./CategoryDetailsSection";

export type CategoryFormProps = {
  initialData?: CategoryDto | null;
  isEdit?: boolean;
};

export const CategoryForm = ({ initialData, isEdit = false }: CategoryFormProps) => {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();

  const [name, setName] = useState(initialData?.name || "");
  const [description, setDescription] = useState(initialData?.description || "");
  const [status, setStatus] = useState<CategoryStatus>(initialData?.status || "ACTIVE");
  const [formError, setFormError] = useState<string | null>(null);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);
    setFieldErrors({});

    if (name.trim().length < 2) {
      setFieldErrors({ name: "Category name must be at least 2 characters." });
      return;
    }

    const payload: CreateCategoryInput & { status?: CategoryStatus } = {
      name: name.trim(),
      description: description.trim() || null,
      ...(isEdit ? { status } : {}),
    };

    startTransition(async () => {
      if (isEdit && initialData) {
        const result = await updateCategoryAction(initialData.id, payload);
        if (!result.success) {
          setFormError(result.error || "Failed to update category.");
          if (result.fieldErrors) setFieldErrors(result.fieldErrors);
          return;
        }
        router.push(`/categories/${initialData.id}?saved=1`);
      } else {
        const result = await createCategoryAction(payload);
        if (!result.success) {
          setFormError(result.error || "Failed to create category.");
          if (result.fieldErrors) setFieldErrors(result.fieldErrors);
          return;
        }
        router.push("/categories?saved=1");
      }
    });
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6" noValidate>
      {formError && (
        <div
          className="rounded-lg border border-danger/40 bg-danger/10 p-4 text-sm text-danger flex items-center justify-between"
          role="alert"
        >
          <span>{formError}</span>
          <button
            type="button"
            onClick={() => setFormError(null)}
            className="text-danger hover:opacity-80"
          >
            <X size={16} />
          </button>
        </div>
      )}

      <CategoryDetailsSection
        name={name}
        onNameChange={setName}
        description={description}
        onDescriptionChange={setDescription}
        status={status}
        onStatusChange={setStatus}
        errors={fieldErrors}
      />

      <div className="flex flex-col-reverse gap-3 pt-2 sm:flex-row sm:items-center sm:justify-end">
        <Link
          href="/categories"
          className="inline-flex h-10 items-center justify-center gap-1.5 rounded-lg border border-border bg-surface-alt px-4 text-sm font-medium text-text-secondary transition-colors hover:border-text-muted hover:text-text-primary"
        >
          <X size={15} />
          <span>Cancel</span>
        </Link>

        <Button
          type="submit"
          variant="primary"
          disabled={isPending}
          className="h-10 px-5 text-sm shadow-xs"
        >
          {isPending ? (
            <>
              <Loader2 size={16} className="animate-spin" />
              <span>Saving...</span>
            </>
          ) : isEdit ? (
            <>
              <Check size={16} />
              <span>Save Changes</span>
            </>
          ) : (
            <>
              <Plus size={16} />
              <span>Create Category</span>
            </>
          )}
        </Button>
      </div>
    </form>
  );
};

