  const handleDelete = () => {
    setActionError(null);
    startTransition(async () => {
      const result = await deleteCategoryAction(category.id);
      if (!result.success) {
        setActionError(result.error || "Failed to delete category.");
        setConfirmDelete(false);
        return;
      }
