            : "This category is not used by any catalogue items. This action cannot be undone."
        }
        confirmLabel="Delete category"
        variant="danger"
        isConfirming={isPending}
        onConfirm={handleDelete}
        onClose={() => setConfirmDelete(false)}
      />
    </section>
  );
};

