"use server";

import { revalidatePath } from "next/cache";
import { resolveUnitContext } from "../context/unit-context";
import { unitRepository } from "../../infrastructure/repositories/prisma-unit-repository";
import { createUnitSchema } from "../validators/unit-schemas";
import { toUnitDto } from "../mappers/unit-mappers";
import { validateUnitCode, validateUnitName, validateUnitPrecision } from "../../domain/rules/unit-rules";
import { UnitDuplicateError } from "../../domain/errors/unit-errors";
import type { CreateUnitInput, UnitActionResult, UnitDto } from "../dto/unit-dto";

export const createUnitAction = async (
  input: CreateUnitInput,
): Promise<UnitActionResult<UnitDto>> => {
  try {
    const parseResult = createUnitSchema.safeParse(input);
    if (!parseResult.success) {
      const fieldErrors: Record<string, string> = {};
      for (const issue of parseResult.error.issues) {
        fieldErrors[issue.path.join(".")] = issue.message;
      }
      return { success: false, error: "Validation failed. Please review the highlighted fields.", fieldErrors };
    }

    const { organizationId } = await resolveUnitContext();
    const data = parseResult.data;
    const code = validateUnitCode(data.code);
    const name = validateUnitName(data.name);
    const precision = validateUnitPrecision(data.precision);

    const existing = await unitRepository.findByCode(organizationId, code);
    if (existing) {
      throw new UnitDuplicateError(code);
    }

    const saved = await unitRepository.create({
      id: `uom_${crypto.randomUUID()}`,
      organizationId,
      name,
      code,
      description: data.description ?? null,
      precision,
      status: "ACTIVE",
      createdAt: new Date(),
      updatedAt: new Date(),
    });

    revalidatePath("/units");
    revalidatePath("/products");
    revalidatePath("/services");

    return { success: true, data: toUnitDto(saved) };
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : "An unexpected server error occurred.";
    return { success: false, error: message };
  }
};

"use server";

import { revalidatePath } from "next/cache";
import { resolveUnitContext } from "../context/unit-context";
import { unitRepository } from "../../infrastructure/repositories/prisma-unit-repository";
import { updateUnitSchema } from "../validators/unit-schemas";
import { toUnitDto } from "../mappers/unit-mappers";
import { validateUnitCode, validateUnitName, validateUnitPrecision } from "../../domain/rules/unit-rules";
import { UnitDuplicateError, UnitNotFoundError } from "../../domain/errors/unit-errors";
import type { UnitOfMeasurement } from "../../domain/entities/unit";
import type { UnitActionResult, UnitDto, UpdateUnitInput } from "../dto/unit-dto";

export const updateUnitAction = async (
  id: string,
  input: UpdateUnitInput,
): Promise<UnitActionResult<UnitDto>> => {
  try {
    const parseResult = updateUnitSchema.safeParse(input);
    if (!parseResult.success) {
      const fieldErrors: Record<string, string> = {};
      for (const issue of parseResult.error.issues) {
        fieldErrors[issue.path.join(".")] = issue.message;
      }
      return { success: false, error: "Validation failed. Please review the highlighted fields.", fieldErrors };
    }

    const { organizationId } = await resolveUnitContext();
    const data = parseResult.data;

    const existing = await unitRepository.findById(organizationId, id);
    if (!existing) {
      throw new UnitNotFoundError(id);
    }

    const patch: Partial<UnitOfMeasurement> = {};
    if (data.name !== undefined) patch.name = validateUnitName(data.name);
    if (data.code !== undefined) {
      const code = validateUnitCode(data.code);
      if (code !== existing.code) {
        const duplicate = await unitRepository.findByCode(organizationId, code);
        if (duplicate && duplicate.id !== id) {
          throw new UnitDuplicateError(code);
        }
      }
      patch.code = code;
    }
    if (data.description !== undefined) patch.description = data.description ?? null;
    if (data.precision !== undefined) patch.precision = validateUnitPrecision(data.precision);
    if (data.status !== undefined) patch.status = data.status;
    patch.updatedAt = new Date();

    const saved = await unitRepository.update(organizationId, id, patch);

    revalidatePath("/units");
    revalidatePath(`/units/${id}`);
    revalidatePath("/products");
    revalidatePath("/services");

    return { success: true, data: toUnitDto(saved) };
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : "An unexpected server error occurred.";
    return { success: false, error: message };
  }
};

"use server";

import { revalidatePath } from "next/cache";
import { isOrganizationAdmin } from "@/features/auth";
import { resolveUnitContext } from "../context/unit-context";
import { unitRepository } from "../../infrastructure/repositories/prisma-unit-repository";
import { productRepository } from "@/features/products/infrastructure/repositories/prisma-product-repository";
import {
  ForbiddenUnitActionError,
  UnitInUseError,
  UnitNotFoundError,
} from "../../domain/errors/unit-errors";
import type { UnitActionResult } from "../dto/unit-dto";

export const deleteUnitAction = async (id: string): Promise<UnitActionResult<void>> => {
  try {
    const { organizationId, memberRole } = await resolveUnitContext();
    if (!isOrganizationAdmin(memberRole)) {
      throw new ForbiddenUnitActionError("Only organization admins can delete units.");
    }

    const existing = await unitRepository.findById(organizationId, id);
    if (!existing) {
      throw new UnitNotFoundError(id);
    }

    const usage = await productRepository.list(organizationId, {
      unit: existing.code,
      limit: 1,
      offset: 0,
    });
    if (usage.totalCount > 0) {
      throw new UnitInUseError(existing.code, usage.totalCount);
    }

    await unitRepository.delete(organizationId, id);

    revalidatePath("/units");
    revalidatePath("/products");
    revalidatePath("/services");

    return { success: true };
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : "An unexpected server error occurred.";
    return { success: false, error: message };
  }
};

"use server";

import { revalidatePath } from "next/cache";
import { resolveUnitContext } from "../context/unit-context";
import { unitRepository } from "../../infrastructure/repositories/prisma-unit-repository";
import { DEFAULT_UNITS, MAX_UNIT_PRECISION } from "../../domain/rules/unit-rules";
import type { UnitActionResult } from "../dto/unit-dto";

export type SeedUnitsResult = {
  created: number;
  skipped: number;
};

/**
 * Seeds the standard units for organizations adopting the master. Additive
 * only: existing records (matched case-insensitively by code) are never
 * modified, so re-running is safe.
 */
export const seedDefaultUnitsAction = async (): Promise<UnitActionResult<SeedUnitsResult>> => {
  try {
    const { organizationId } = await resolveUnitContext();

    let created = 0;
    let skipped = 0;
    for (const def of DEFAULT_UNITS) {
      const existing = await unitRepository.findByCode(organizationId, def.code);
      if (existing) {
        skipped += 1;
        continue;
      }
      await unitRepository.create({
        id: `uom_${crypto.randomUUID()}`,
        organizationId,
        name: def.name,
        code: def.code,
        description: def.description,
        precision: MAX_UNIT_PRECISION,
        status: "ACTIVE",
        createdAt: new Date(),
        updatedAt: new Date(),
      });
      created += 1;
    }

    revalidatePath("/units");
    revalidatePath("/products");
    revalidatePath("/services");

    return { success: true, data: { created, skipped } };
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : "An unexpected server error occurred.";
    return { success: false, error: message };
  }
};

