// One-shot isolated HSN/SAC import validation. Creates a throwaway database,
// applies the full migration chain, runs the importer twice (idempotency),
// then drops the database. Never touches the development database.
const { spawnSync } = require("node:child_process");
const fs = require("node:fs");
const path = require("node:path");
const { Client } = require("pg");

const readDotEnvDatabaseUrl = () => {
  const envPath = path.join(process.cwd(), ".env");
  const content = fs.readFileSync(envPath, "utf8");
  const line = content.split(/\r?\n/).find((l) => l.trim().startsWith("DATABASE_URL="));
  if (!line) throw new Error("DATABASE_URL not found in .env");
  return line.slice("DATABASE_URL=".length).trim().replace(/^"|"$/g, "");
};

const run = (cmd, args, env) => {
  const result = spawnSync(cmd, args, { env, encoding: "utf8", timeout: 300000, shell: true });
  if (result.stdout) console.log(result.stdout);
  if (result.status !== 0) {
    console.log(result.stderr);
    throw new Error(`${cmd} ${args.join(" ")} failed with status ${result.status}`);
  }
};

const main = async () => {
  const baseUrl = readDotEnvDatabaseUrl();
  const dbName = `aventra_hsntest_${Date.now()}`;
  const admin = new Client({ connectionString: baseUrl });
  await admin.connect();
  await admin.query(`CREATE DATABASE "${dbName}"`);
  await admin.end();
  const isolatedUrl = baseUrl.replace(/\/[^/?]+(\?|$)/, `/${dbName}$1`);
  console.log(`created isolated database ${dbName}`);
  try {
    run("npx", ["prisma", "migrate", "deploy"], { ...process.env, DATABASE_URL: isolatedUrl });
